-- ES02 hosted-compat C5 — semantic ACL comparison for capability contract.
-- Root cause: pinned proacl/relacl text equality fails when privilege entries are
-- semantically identical but ordered differently (e.g. service_role before authenticated).
-- Retains frozen expected arrays, body hashes, result/owner/config/definer/volatility/RLS/types.
-- Replaces only ACL text equality with aclexplode tuple set equality plus effective
-- anon/authenticated/service_role rights vs pinned PUBLIC/direct grants.
-- Does not change business grants, C3 guard, preflight/postflight/deny fences, or probe.

create or replace function private.vel_broker_capability_contract_matches()
