   as expected(sig text,body text,result text,owner text,acl text,config jsonb,security boolean,volatility text)
  left join pg_catalog.pg_proc p on p.oid=pg_catalog.to_regprocedure(expected.sig)
  where p.oid is null
   or md5(replace(p.prosrc,chr(13),'')) is distinct from expected.body
   or pg_catalog.pg_get_function_result(p.oid) is distinct from expected.result
   or pg_catalog.pg_get_userbyid(p.proowner) is distinct from expected.owner
   or exists (
     select 1 from (
       select a.grantee, a.grantor, a.privilege_type, a.is_grantable
       from aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
       except
       select e.grantee, e.grantor, e.privilege_type, e.is_grantable
       from aclexplode(expected.acl::aclitem[]) e
     ) fn_extra
   )
   or exists (
     select 1 from (
       select e.grantee, e.grantor, e.privilege_type, e.is_grantable
       from aclexplode(expected.acl::aclitem[]) e
       except
       select a.grantee, a.grantor, a.privilege_type, a.is_grantable
       from aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
     ) fn_missing
   )
   or has_function_privilege('anon', p.oid, 'EXECUTE') is distinct from exists (
     select 1 from aclexplode(expected.acl::aclitem[]) e
     where e.privilege_type = 'EXECUTE'
       and (e.grantee = 0 or e.grantee = (select oid from pg_roles where rolname = 'anon'))
   )
   or has_function_privilege('authenticated', p.oid, 'EXECUTE') is distinct from exists (
     select 1 from aclexplode(expected.acl::aclitem[]) e
     where e.privilege_type = 'EXECUTE'
       and (e.grantee = 0 or e.grantee = (select oid from pg_roles where rolname = 'authenticated'))
   )
   or has_function_privilege('service_role', p.oid, 'EXECUTE') is distinct from exists (
     select 1 from aclexplode(expected.acl::aclitem[]) e
     where e.privilege_type = 'EXECUTE'
       and (e.grantee = 0 or e.grantee = (select oid from pg_roles where rolname = 'service_role'))
   )
   or to_jsonb(p.proconfig) is distinct from expected.config
   or p.prosecdef is distinct from expected.security
   or p.provolatile::text is distinct from expected.volatility
 ) and not exists (
