     select 1
     from (values
       ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')
     ) as priv(name)
     where has_table_privilege('anon', c.oid, priv.name) is distinct from exists (
             select 1 from aclexplode(expected.acl::aclitem[]) e
             where e.privilege_type = priv.name
               and (e.grantee = 0 or e.grantee = (select oid from pg_roles where rolname = 'anon'))
           )
        or has_table_privilege('authenticated', c.oid, priv.name) is distinct from exists (
             select 1 from aclexplode(expected.acl::aclitem[]) e
             where e.privilege_type = priv.name
               and (e.grantee = 0 or e.grantee = (select oid from pg_roles where rolname = 'authenticated'))
           )
        or has_table_privilege('service_role', c.oid, priv.name) is distinct from exists (
             select 1 from aclexplode(expected.acl::aclitem[]) e
             where e.privilege_type = priv.name
               and (e.grantee = 0 or e.grantee = (select oid from pg_roles where rolname = 'service_role'))
           )
   )
   or c.relrowsecurity is distinct from expected.rls
 );
$contract$;
alter function private.vel_broker_capability_contract_matches() owner to postgres;
revoke all on function private.vel_broker_capability_contract_matches() from public,anon,authenticated,service_role;
